let syms = find_symbols("JNI_OnLoad");
for s in syms {
  report("JNI_OnLoad Entry", s.address, "INFO", "Size: " + s.size + " bytes");
  let insns = disasm(s.address, 128);
  for ins in insns {
    if ins.mnemonic == "bl" || ins.mnemonic == "blr" || ins.mnemonic == "call" {
      report("JNI_OnLoad Call", ins.address, "INFO", ins.mnemonic + " " + ins.op_str);
    }
  }
}
